# Open the selected claims together. Each that can be opened is opened (and audited) as a single
# open would be, in list order; each that cannot is left as it is. Answers how many of each.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkOpen
  next: open
open:
  class: net.officefloor.hq.app.claim.OpenClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen
  govern: [ transaction ]
# Open, settle or void a claim. Validate before Load so an unknown action is a 400, not a 404;
# a change the claim's status does not allow is a 409 and writes nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimStatus
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused change writes no line.
record:
  class: net.officefloor.hq.app.claim.RecordClaimStatusChanged
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { claimsKey } from '../claims/useClaims';
import { useSelectedClaims } from './useSelectedClaims';

/**
 * Open the ticked claims together. Each that can be opened is opened and numbered in list order
 * (people in list order, each person's newest claim first); each that cannot is left as it is.
 * Shows how many were opened and how many refused; the counts go while the next press runs.
 */
function BulkOpen({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const [selected, setSelected] = useSelectedClaims();
  const bulk = useMutation({
    mutationFn: (claimIds: number[]) =>
      postJson<{ opened: number; refused: number }>(`/api/sheets/${encodeURIComponent(sheet)}/bulk-open`, { claimIds, user }),
    onSuccess: () => setSelected([]),
    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
  });
  return (
    <section data-testid="bulk-open-panel">
      <button
        type="button"
        data-testid="bulk-open"
        disabled={bulk.isPending}
        onClick={() => {
          bulk.reset();
          bulk.mutate(selected);
        }}
      >
        Open selected ({selected.length})
      </button>
      {bulk.isSuccess && (
        <span>
          {' '}
          Opened <strong data-testid="bulk-opened">{bulk.data.opened}</strong>, refused{' '}
          <strong data-testid="bulk-refused">{bulk.data.refused}</strong>
        </span>
      )}
      {bulk.isError && (
        <span data-testid="bulk-open-error" role="alert">
          {' '}
          {selected.length === 0 ? 'Select the claims to open.' : 'Could not open the selected claims.'}
        </span>
      )}
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 15, Component: BulkOpen });
import { useSearchParam } from '../../url/useSearchParam';

const asIds = (raw: unknown): number[] =>
  Array.isArray(raw) ? raw.map(Number).filter((n) => Number.isInteger(n)) : [];

/** The claims ticked for a bulk action, by id. Kept in the URL, like any selection. */
export function useSelectedClaims(): [number[], (ids: number[]) => void] {
  const [ids, set] = useSearchParam('selected', asIds);
  return [ids, (next) => set(next.length === 0 ? undefined : next)];
}
