package net.officefloor.hq.app.claim;

import java.util.Set;

/** A validated bulk open: the selected claims and who opens them. */
public record BulkOpen(Set<Long> claimIds, String user) {
}
package net.officefloor.hq.app.claim;

import java.util.List;

/** Body of a bulk open: the selected claims' ids and who opens them. */
public record BulkOpenRequest(List<Long> claimIds, String user) {
}
package net.officefloor.hq.app.claim;

/** How many of the selected claims a bulk open opened, and how many it refused. */
public record BulkOpenResult(int opened, int refused) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithBulkOpen {
    public void respond(@Val BulkOpenResult result, ObjectResponse<BulkOpenResult> response) {
        response.send(result);
    }
}
package net.officefloor.hq.app.claim;

import java.util.LinkedHashSet;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateBulkOpen {
    public void validate(@RequestBody BulkOpenRequest request, Out<BulkOpen> body) throws InvalidSheetRequestException {
        if (request == null || request.claimIds() == null || request.claimIds().isEmpty()) {
            throw new InvalidSheetRequestException("Select the claims to open");
        }
        body.set(new BulkOpen(new LinkedHashSet<>(request.claimIds()), request.user()));
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Snapshot;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Opens each selected claim that can be opened, in list order (people in list order, each
 *  person's newest claim first), so their numbers follow that order. Each is opened as a single
 *  open would be — its own audit line, then the figures it moved; one that cannot be opened (or is
 *  not on the sheet) is left as it is and counted as refused. */
public class OpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpen bulk, Claims claims, People people,
            ClaimNumbers numbers, Figures figures, ClosedPeriods closedPeriods, Settings settings, Rollup rollup,
            ClaimLog log, Audit audit, Out<BulkOpenResult> result) {
        ClaimStatusChange change = new ClaimStatusChange(ClaimAction.OPEN, bulk.user());
        ApplyClaimStatus apply = new ApplyClaimStatus();
        RecordClaimStatusChanged record = new RecordClaimStatusChanged();
        List<Claim> all = claims.onSheet(sheetId);
        int opened = 0;
        for (Person person : people.onSheet(sheetId)) {
            for (Claim listed : all) {
                if (listed.getPersonId() != person.getId() || !bulk.claimIds().contains(listed.getId())) continue;
                Claim claim = claims.find(sheetId, listed.getId());
                Snapshot before = rollup.snapshot(sheetId);
                try {
                    apply.apply(change, claim, numbers, people, figures, closedPeriods, settings);
                } catch (ClaimStatusRefusedException | PeriodClosedException e) {
                    continue;
                }
                claims.save(claim);
                record.record(change, claim, people, log, audit);
                rollup.record(sheetId, before, bulk.user());
                opened++;
            }
        }
        result.set(new BulkOpenResult(opened, bulk.claimIds().size() - opened));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import java.math.BigDecimal;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.plugin.variable.Val;

/** Moves the claim to the action's status, refusing a change its current status does not allow.
 *  Opening gives the claim its number (see {@link ClaimNumbers}); a voided claim keeps it (and it is never reused).
 *  Settling fixes the claim's due at the figure it has then: the one its person's last statement
 *  bound it to, else its person's grade's rate in force on the claim's date, at least the sheet's floor, plus its late charge then; with no rate it stays live. The user who opened a claim may not settle it.
 *  When a clerk settles a claim whose due is over the sheet's clerk limit (a due of n/a is within any
 *  limit) it goes PENDING instead, its due still live; a steward settles anything. Only a steward
